WHERE e.company_id = #{companyId}
AND e.base_period = #{basePeriod}
AND e.facility_id = #{facilityId}
AND f.facility_name ILIKE '%' || #{search} || '%'
AND e.reflection_status = #{reflectionStatus}
AND e.approval_status = #{approvalStatus}
AND e.approval_status = 'APPROVED'
ORDER BY e.base_period DESC,
         CASE WHEN f.facility_type = 'HQ' THEN 0 ELSE 1 END,
         f.facility_name

SELECT s.*, f.facility_name, f.facility_type
FROM social_monthly_data s
JOIN company_facilities f ON f.id = s.facility_id
WHERE s.company_id = #{companyId}
AND s.base_period = #{basePeriod}
AND s.facility_id = #{facilityId}
AND f.facility_name ILIKE '%' || #{search} || '%'
AND s.reflection_status = #{reflectionStatus}
AND s.approval_status = #{approvalStatus}
AND s.approval_status = 'APPROVED'
ORDER BY s.base_period DESC,
         CASE WHEN f.facility_type = 'HQ' THEN 0 ELSE 1 END,
         f.facility_name

SELECT g.*, f.facility_name AS headquarters_name
FROM governance_monthly_data g
LEFT JOIN company_facilities f ON f.id = g.headquarters_facility_id
WHERE g.company_id = #{companyId}
AND g.base_period = #{basePeriod}
AND g.reflection_status = #{reflectionStatus}
AND g.approval_status = #{approvalStatus}
AND g.approval_status = 'APPROVED'
ORDER BY g.base_period DESC


WHERE e.company_id = #{companyId} AND e.facility_id = #{facilityId}
  AND e.base_period LIKE CONCAT(#{year}, '-%')
ORDER BY e.base_period

SELECT r.id, r.run_id, r.company_id, r.facility_id, r.domain, r.source_system,
       r.source_record_id, r.base_period, r.payload::text AS payload,
       r.validation_status, r.error_message, r.collected_at, f.facility_name
FROM integration_raw_data r
LEFT JOIN company_facilities f ON f.id = r.facility_id
WHERE r.company_id = #{companyId}
AND r.facility_id = #{facilityId}
AND r.domain = #{domain}
AND r.base_period = #{basePeriod}
ORDER BY r.collected_at DESC
LIMIT #{limit}

SELECT * FROM integration_runs
WHERE company_id = #{companyId}
AND domain = #{domain}
AND base_period = #{basePeriod}
ORDER BY started_at DESC
LIMIT #{limit}

SELECT COUNT(*) FROM environment_monthly_data
WHERE company_id = #{companyId} AND base_period = #{basePeriod}
  AND collection_status = 'COLLECTED'
  AND reflection_status = 'NOT_REFLECTED'
  AND approval_status != 'APPROVED'
AND facility_id = #{facilityId}

SELECT COUNT(*) FROM social_monthly_data
WHERE company_id = #{companyId} AND base_period = #{basePeriod}
  AND collection_status = 'COLLECTED'
  AND reflection_status = 'NOT_REFLECTED'
  AND approval_status != 'APPROVED'
AND facility_id = #{facilityId}

