UPDATE environment_monthly_data
SET reflection_status = 'REFLECTED', approval_status = 'DRAFT', reflected_at = CURRENT_TIMESTAMP,
    approved_at = NULL, updated_at = CURRENT_TIMESTAMP
WHERE company_id = #{companyId} AND base_period = #{basePeriod}
  AND reflection_status = 'NOT_REFLECTED' AND approval_status != 'APPROVED'
AND facility_id = #{facilityId}

UPDATE social_monthly_data
SET reflection_status = 'REFLECTED', approval_status = 'DRAFT', reflected_at = CURRENT_TIMESTAMP,
    approved_at = NULL, updated_at = CURRENT_TIMESTAMP
WHERE company_id = #{companyId} AND base_period = #{basePeriod}
  AND reflection_status = 'NOT_REFLECTED' AND approval_status != 'APPROVED'
AND facility_id = #{facilityId}
